<?php
require_once __DIR__.'/../document_reminders/services/UserSmtpCredentialService.php';
require_once __DIR__.'/AttendancePolicyService.php';
function payrollSenderStatus($user){$service=new UserSmtpCredentialService();echo json_encode(['success'=>true]+$service->status((int)$user['id']));}
function payrollSenderSave($user){try{$service=new UserSmtpCredentialService();$result=$service->saveAndVerify($user,json_decode(file_get_contents('php://input'),true)?:[]);echo json_encode(['success'=>true,'message'=>'Sender mailbox authenticated and saved securely.']+$result);}catch(Throwable $error){http_response_code(422);echo json_encode(['success'=>false,'message'=>$error->getMessage()]);}}
function payrollSenderRemove($user){(new UserSmtpCredentialService())->remove((int)$user['id']);echo json_encode(['success'=>true,'message'=>'Sender mailbox configuration removed.']);}
function payrollKey(){ $secret=(string)getenv('MAIL_CREDENTIAL_KEY');$file=__DIR__.'/../../config/mail-credential-key.php';if(strlen($secret)<32&&is_file($file))$secret=(string)require $file;if(strlen($secret)<32)throw new RuntimeException('A secure payroll encryption key is required.');return hash('sha256',$secret,true); }
function payrollEncryptValue($value){if($value===null||$value==='')return $value;$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt((string)$value,'aes-256-gcm',payrollKey(),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new RuntimeException('Payroll data encryption failed.');return 'enc:v1:'.base64_encode($iv.$tag.$cipher);}
function payrollDecryptValue($value){if(!is_string($value)||!str_starts_with($value,'enc:v1:'))return $value;$raw=base64_decode(substr($value,7),true);if($raw===false||strlen($raw)<29)return '';$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',payrollKey(),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));return $plain===false?'':$plain;}
function payrollSensitiveKeys(){return ['father_name','pan_number','uan_number','pf_account_number','esi_number','bank_name','bank_account_number','ifsc_code','permanent_address','date_of_birth'];}
function payrollSecureData($data,$encrypt=true){foreach(payrollSensitiveKeys() as $key)if(array_key_exists($key,$data))$data[$key]=$encrypt?payrollEncryptValue($data[$key]):payrollDecryptValue($data[$key]);return $data;}function payrollMonth(){ $m=$_GET['month']??date('Y-m'); if(!preg_match('/^\d{4}-\d{2}$/',$m))throw new InvalidArgumentException('A valid payroll month is required.'); return $m; }
function payrollDecode($row){if(!$row)return null;$row['id']=(int)$row['id'];$row['gross_earnings']=(float)$row['gross_earnings'];$row['total_deductions']=(float)$row['total_deductions'];$row['net_pay']=(float)$row['net_pay'];$row['snapshot']=payrollSecureData(json_decode($row['payroll_snapshot'],true)?:[],false);unset($row['payroll_snapshot']);return $row;}
function payrollFind($id){global $conn;$s=$conn->prepare('SELECT * FROM employee_payslips WHERE id=?');$s->bind_param('i',$id);$s->execute();return payrollDecode($s->get_result()->fetch_assoc());}
function payrollRoster(){
 global $conn;$m=payrollMonth();$start=$m.'-01';$end=(new DateTimeImmutable($start))->modify('last day of this month')->format('Y-m-d');
 $s=$conn->prepare("SELECT e.id,e.employee_id,TRIM(CONCAT_WS(' ',e.firstname,e.lastname)) legal_name,p.position_name role,
 e.payroll_email payroll_email,e.monthly_salary,
 COUNT(DISTINCT a.date) present_days,SUM(CASE WHEN a.work_status='half_day' THEN 1 ELSE 0 END) half_days,
 ps.id payslip_id,ps.status payslip_status,ps.payroll_snapshot,ps.payslip_number,ps.gross_earnings,ps.total_deductions,ps.net_pay,ps.generated_at,ps.sent_at
 FROM employees e JOIN users u ON u.id=e.user_id LEFT JOIN positions p ON p.id=u.position_id
 LEFT JOIN attendance a ON a.employee_id=e.id AND a.date BETWEEN ? AND ?
 LEFT JOIN employee_payslips ps ON ps.employee_id=e.id AND ps.pay_month=?
 WHERE e.user_id IS NOT NULL GROUP BY e.id,u.email,p.position_name,ps.id ORDER BY e.firstname,e.lastname");
 $s->bind_param('sss',$start,$end,$m);$s->execute();$out=[];$r=$s->get_result();while($x=$r->fetch_assoc()){if($x['payslip_id']){$x['payslip']=payrollDecode(['id'=>$x['payslip_id'],'status'=>$x['payslip_status'],'payroll_snapshot'=>$x['payroll_snapshot'],'payslip_number'=>$x['payslip_number'],'gross_earnings'=>$x['gross_earnings'],'total_deductions'=>$x['total_deductions'],'net_pay'=>$x['net_pay'],'generated_at'=>$x['generated_at'],'sent_at'=>$x['sent_at']]);}unset($x['payroll_snapshot'],$x['payslip_number'],$x['gross_earnings'],$x['total_deductions'],$x['net_pay'],$x['generated_at'],$x['sent_at']);$out[]=$x;}echo json_encode(['success'=>true,'data'=>$out]);
}
function payrollDraft($employeeId){
 global $conn;$m=payrollMonth();$start=new DateTimeImmutable($m.'-01');$end=$start->modify('last day of this month');$s=$conn->prepare("SELECT e.id,e.employee_id,TRIM(CONCAT_WS(' ',e.firstname,e.lastname)) employee_name,p.position_name designation,e.payroll_email payroll_email,e.monthly_salary,e.address permanent_address,e.birthdate date_of_birth,e.gender,e.payroll_profile FROM employees e JOIN users u ON u.id=e.user_id LEFT JOIN positions p ON p.id=u.position_id WHERE e.id=?");$s->bind_param('i',$employeeId);$s->execute();$d=$s->get_result()->fetch_assoc();if(!$d){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Employee not found.']);return;}
 $weekends=0;$working=0;for($day=$start;$day<=$end;$day=$day->modify('+1 day')){in_array((int)$day->format('N'),[6,7])?$weekends++:$working++;}
 $a=$conn->prepare("SELECT COUNT(DISTINCT date) present,SUM(work_status='half_day') halfs FROM attendance WHERE employee_id=? AND date BETWEEN ? AND ?");$a1=$start->format('Y-m-d');$a2=$end->format('Y-m-d');$a->bind_param('iss',$employeeId,$a1,$a2);$a->execute();$att=$a->get_result()->fetch_assoc();
 $h=$conn->prepare("SELECT COUNT(*) total FROM holidays WHERE holiday_date BETWEEN ? AND ? AND DAYOFWEEK(holiday_date) NOT IN(1,7)");$h->bind_param('ss',$a1,$a2);$h->execute();$hol=(float)$h->get_result()->fetch_assoc()['total'];
 $l=$conn->prepare("SELECT leave_type,SUM((DATEDIFF(LEAST(end_date,?),GREATEST(start_date,?))+1)*IF(duration='full_day',1,.5)) days FROM leave_requests WHERE employee_id=? AND status='approved' AND start_date<=? AND end_date>=? GROUP BY leave_type");$l->bind_param('issss',$a2,$a1,$employeeId,$a2,$a1);$l->execute();$lv=['pl_days'=>0,'cl_days'=>0,'upl_days'=>0];$lr=$l->get_result();while($x=$lr->fetch_assoc()){if(in_array($x['leave_type'],['paid','sick']))$lv['pl_days']+=(float)$x['days'];elseif($x['leave_type']==='casual')$lv['cl_days']+=(float)$x['days'];elseif($x['leave_type']==='unpaid')$lv['upl_days']+=(float)$x['days'];}
 $profile=payrollSecureData(json_decode($d['payroll_profile']??'',true)?:[],false);unset($d['payroll_profile']);$d=array_merge($d,$profile);$d['location']='Visakhapatnam';
 $salary=(float)($d['monthly_salary']??0);
 $defaults=['monthly_salary'=>$salary,'basic_salary'=>round($salary*.5,2),'hra'=>round($salary*.2,2),'special_allowance'=>round($salary*.3,2),'bonus'=>0,'overtime'=>0,'reimbursement'=>0,'other_earnings'=>0,'us_tax'=>200,'pf'=>0,'esi'=>0,'insurance'=>0,'loan_advance'=>0,'other_deductions'=>0,'professional_tax'=>0,'father_name'=>'','pan_number'=>'','uan_number'=>'','pf_account_number'=>'','esi_number'=>'','bank_name'=>'','bank_account_number'=>'','ifsc_code'=>'','date_of_joining'=>'','pay_mode'=>'Bank Transfer','department'=>'','location'=>'Visakhapatnam','leave_cl_opening'=>0,'leave_cl_available'=>0,'leave_cl_carried'=>0,'leave_cl_max'=>0,'leave_cl_encashed'=>0,'leave_cl_previous_used'=>0,'leave_pl_opening'=>0,'leave_pl_available'=>0,'leave_pl_carried'=>0,'leave_pl_max'=>0,'leave_pl_encashed'=>0,'leave_pl_previous_used'=>0,'comp_off_opening'=>0,'comp_off_available'=>0,'comp_off_carried'=>0,'comp_off_max'=>0,'comp_off_encashed'=>0,'comp_off_previous_used'=>0,'comp_off_availed'=>0,'employer_pf'=>0,'employer_esi'=>0,'pension_fund'=>0,'ctc_other'=>0,'notes'=>''];
 $previous=$conn->prepare("SELECT pay_month,payroll_snapshot FROM employee_payslips WHERE employee_id=? AND pay_month<? ORDER BY pay_month DESC,id DESC LIMIT 1");
 $previous->bind_param('is',$employeeId,$m);$previous->execute();$saved=$previous->get_result()->fetch_assoc();
 if($saved){$snapshot=json_decode($saved['payroll_snapshot'],true)?:[];foreach(['monthly_salary','basic_salary','hra','special_allowance','us_tax','pf','esi','insurance'] as $key){if(array_key_exists($key,$snapshot))$defaults[$key]=(float)$snapshot[$key];}$defaults['previous_pay_month']=$saved['pay_month'];}
 $salary=(float)$defaults['monthly_salary'];$daily=$working?($salary/$working):0;
 $policy=(new AttendancePolicyService())->calculate($employeeId,$m);
 $current=['pay_month'=>$m,'currency'=>'INR','working_days'=>$working,'worked_days'=>(float)($att['present']??0),'max_payable_days'=>$working,'net_paid_days'=>max(0,$working-$lv['upl_days']),'days_off'=>$weekends,'unpaid_holidays'=>0,'weekend_days'=>$weekends,'holiday_days'=>$hol,'present_days'=>(float)($att['present']??0),'half_days'=>(float)($att['halfs']??0),'payable_days'=>max(0,$working-$lv['upl_days']),'unpaid_leave_deduction'=>round($daily*$lv['upl_days'],2)];
 $d=array_merge($d,$defaults,$lv,$current,$policy);$daily=(float)($d['working_days']??0)>0?($salary/(float)$d['working_days']):0;$d['unpaid_leave_deduction']=round($daily*(float)($d['upl_days']??0),2);echo json_encode(['success'=>true,'data'=>$d]);
}
function payrollGenerate($user){
 global $conn;$d=json_decode(file_get_contents('php://input'),true)?:[];$d['location']='Visakhapatnam';$required=['id','pay_month','payroll_email','monthly_salary'];foreach($required as $k)if(empty($d[$k])&&$d[$k]!==0){http_response_code(422);echo json_encode(['success'=>false,'message'=>$k.' is required.']);return;}if(!filter_var($d['payroll_email'],FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'A valid employee payroll email is required.']);return;}
 $earn=['basic_salary','hra','special_allowance','bonus','overtime','reimbursement','other_earnings'];$cuts=['us_tax','pf','esi','professional_tax','insurance','loan_advance','unpaid_leave_deduction','other_deductions'];$gross=0;$ded=0;foreach($earn as $k){$d[$k]=max(0,(float)($d[$k]??0));$gross+=$d[$k];}foreach($cuts as $k){$d[$k]=max(0,(float)($d[$k]??0));$ded+=$d[$k];}$net=$gross-$ded;if($net<0){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Deductions cannot exceed gross earnings.']);return;}
 $id=(int)$d['id'];$num='BDT-'.str_replace('-','',$d['pay_month']).'-'.str_pad((string)$id,5,'0',STR_PAD_LEFT);$d['payslip_number']=$num;$d['currency']='INR';$d['gross_earnings']=$gross;$d['total_deductions']=$ded;$d['net_pay']=$net;$profileKeys=['father_name','pan_number','uan_number','pf_account_number','esi_number','bank_name','bank_account_number','ifsc_code','date_of_joining','pay_mode','permanent_address','department','location','date_of_birth','gender','leave_cl_opening','leave_cl_available','leave_cl_carried','leave_cl_max','leave_cl_encashed','leave_cl_previous_used','leave_pl_opening','leave_pl_available','leave_pl_carried','leave_pl_max','leave_pl_encashed','leave_pl_previous_used','comp_off_opening','comp_off_available','comp_off_carried','comp_off_max','comp_off_encashed','comp_off_previous_used','comp_off_availed','employer_pf','employer_esi','pension_fund','ctc_other'];$profile=[];foreach($profileKeys as $key)$profile[$key]=$d[$key]??null;$profileJson=json_encode(payrollSecureData($profile,true),JSON_UNESCAPED_SLASHES);$json=json_encode(payrollSecureData($d,true),JSON_UNESCAPED_SLASHES);$uid=(int)$user['id'];
 $conn->begin_transaction();try{$u=$conn->prepare('UPDATE employees SET payroll_email=?,monthly_salary=?,payroll_profile=?,date_of_joining=? WHERE id=?');$sal=(float)$d['monthly_salary'];$joining=$d['date_of_joining']?:null;$u->bind_param('sdssi',$d['payroll_email'],$sal,$profileJson,$joining,$id);$u->execute();$s=$conn->prepare("INSERT INTO employee_payslips(employee_id,pay_month,payslip_number,payroll_snapshot,gross_earnings,total_deductions,net_pay,generated_by) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('isssdddi',$id,$d['pay_month'],$num,$json,$gross,$ded,$net,$uid);$s->execute();$pid=$conn->insert_id;$conn->commit();echo json_encode(['success'=>true,'message'=>'Payslip generated and saved. Review it before sending.','data'=>payrollFind($pid)]);}catch(Throwable $e){$conn->rollback();http_response_code(409);echo json_encode(['success'=>false,'message'=>str_contains($e->getMessage(),'Duplicate')?'A payslip already exists for this employee and month.':'Payslip could not be saved.']);}
}
function payrollUpdate($recordId,$user){
 global $conn;$existing=payrollFind($recordId);if(!$existing){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Payslip not found.']);return;}
 $d=json_decode(file_get_contents('php://input'),true)?:[];$employeeId=(int)($existing['snapshot']['id']??0);$d['location']='Visakhapatnam';
 if((int)($d['id']??0)!==$employeeId){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Payslip employee cannot be changed.']);return;}
 if(!filter_var($d['payroll_email']??'',FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'A valid employee payroll email is required.']);return;}
 $earn=['basic_salary','hra','special_allowance','bonus','overtime','reimbursement','other_earnings'];$cuts=['us_tax','pf','esi','professional_tax','insurance','loan_advance','unpaid_leave_deduction','other_deductions'];$gross=0;$ded=0;
 foreach($earn as $key){$d[$key]=max(0,(float)($d[$key]??0));$gross+=$d[$key];}foreach($cuts as $key){$d[$key]=max(0,(float)($d[$key]??0));$ded+=$d[$key];}
 $net=$gross-$ded;if($net<0){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Deductions cannot exceed gross earnings.']);return;}
 $d['payslip_number']=$existing['payslip_number'];$d['currency']='INR';$d['gross_earnings']=$gross;$d['total_deductions']=$ded;$d['net_pay']=$net;
 $profileKeys=['father_name','pan_number','uan_number','pf_account_number','esi_number','bank_name','bank_account_number','ifsc_code','date_of_joining','pay_mode','permanent_address','department','location','date_of_birth','gender','leave_cl_opening','leave_cl_available','leave_cl_carried','leave_cl_max','leave_cl_encashed','leave_cl_previous_used','leave_pl_opening','leave_pl_available','leave_pl_carried','leave_pl_max','leave_pl_encashed','leave_pl_previous_used','comp_off_opening','comp_off_available','comp_off_carried','comp_off_max','comp_off_encashed','comp_off_previous_used','comp_off_availed','employer_pf','employer_esi','pension_fund','ctc_other'];$profile=[];foreach($profileKeys as $key)$profile[$key]=$d[$key]??null;$profileJson=json_encode(payrollSecureData($profile,true),JSON_UNESCAPED_SLASHES);$json=json_encode(payrollSecureData($d,true),JSON_UNESCAPED_SLASHES);$salary=max(0,(float)($d['monthly_salary']??0));$email=$d['payroll_email'];$uid=(int)$user['id'];
 $conn->begin_transaction();try{$employee=$conn->prepare('UPDATE employees SET payroll_email=?,monthly_salary=?,payroll_profile=?,date_of_joining=? WHERE id=?');$joining=$d['date_of_joining']?:null;$employee->bind_param('sdssi',$email,$salary,$profileJson,$joining,$employeeId);$employee->execute();
 $save=$conn->prepare("UPDATE employee_payslips SET payroll_snapshot=?,gross_earnings=?,total_deductions=?,net_pay=?,status='generated',generated_by=?,generated_at=NOW(),sent_at=NULL WHERE id=?");$save->bind_param('sdddii',$json,$gross,$ded,$net,$uid,$recordId);$save->execute();$conn->commit();
 echo json_encode(['success'=>true,'message'=>'Payslip changes saved. Review the updated document before sending.','data'=>payrollFind($recordId)]);
 }catch(Throwable $error){$conn->rollback();http_response_code(422);echo json_encode(['success'=>false,'message'=>'Payslip changes could not be saved.']);}
}
function payrollPdf($p){
 $d=array_merge(array_fill_keys(['father_name','date_of_joining','pan_number','bank_account_number','uan_number','pf_account_number','bank_name','pay_mode','designation','esi_number','department','location','gender','date_of_birth','permanent_address','half_days','pl_days','cl_days','upl_days','weekend_days','holiday_days','working_days','present_days','payable_days'],''),$p['snapshot']);$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$m=fn($v)=>number_format((float)($v??0),2);$month=DateTimeImmutable::createFromFormat('!Y-m',$d['pay_month']??'');$period=$month?$month->format('F Y'):($d['pay_month']??'');$logo=__DIR__.'/../../assets/beedata-logo.png';$logoData=is_file($logo)?'data:image/png;base64,'.base64_encode(file_get_contents($logo)):'';
 $gross=(float)$p['gross_earnings'];$ded=(float)$p['total_deductions'];$net=(float)$p['net_pay'];$employerPf=(float)($d['employer_pf']??0);$employerEsi=(float)($d['employer_esi']??0);$pension=(float)($d['pension_fund']??0);$ctcOther=(float)($d['ctc_other']??0);$ctc=$gross+$employerPf+$employerEsi+$pension+$ctcOther;
 $rows=[['Basic Salary',$d['basic_salary']??0,'Provident Fund (PF)',$d['pf']??0],['HRA / Housing',$d['hra']??0,'ESI',$d['esi']??0],['Special Allowance',$d['special_allowance']??0,'Income Tax / TDS',$d['us_tax']??0],['Bonus / Incentive',$d['bonus']??0,'Professional Tax',$d['professional_tax']??0],['Overtime',$d['overtime']??0,'UPL / Absence',$d['unpaid_leave_deduction']??0],['Reimbursement',$d['reimbursement']??0,'Insurance / Advance / Other',(float)($d['insurance']??0)+(float)($d['loan_advance']??0)+(float)($d['other_deductions']??0)],['Other Earnings',$d['other_earnings']??0,'','']];$payRows='';foreach($rows as $r)$payRows.='<tr><td>'.$e($r[0]).'</td><td class="num">'.$m($r[1]).'</td><td>'.$e($r[2]).'</td><td class="num">'.($r[3]===''?'':$m($r[3])).'</td></tr>';
 $leaveRows='';foreach([['CL',$d['leave_cl_opening']??0,$d['cl_days']??0],['PL',$d['leave_pl_opening']??0,$d['pl_days']??0],['COMP OFF',$d['comp_off_opening']??0,$d['comp_off_availed']??0]] as $r){$close=max(0,(float)$r[1]-(float)$r[2]);$leaveRows.='<tr><td>'.$r[0].'</td><td class="num">'.$m($r[1]).'</td><td class="num">'.$m($r[2]).'</td><td class="num">'.$m($close).'</td></tr>';}
 $html='<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:20px 24px}body{font-family:DejaVu Sans,sans-serif;font-size:8px;color:#111}.head{text-align:center}.head img{width:145px}.head h2{margin:3px 0 1px;font-size:13px}.head p{margin:1px}.title{font-weight:bold;font-size:11px;margin:8px 0 5px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #333;padding:3px 4px;vertical-align:top}th{background:#edf3f8;text-align:left}.info td{width:25%}.label{font-weight:bold;color:#374151}.section{margin-top:6px}.num{text-align:right}.strong{font-weight:bold}.net{font-size:10px;background:#eef6ff}.footer{text-align:right;margin-top:18px;font-weight:bold}.muted{font-size:7px;color:#555}</style></head><body><div class="head"><img src="'.$logoData.'"><h2>BEEDATA TECHNOLOGIES</h2><p>H.NO 8-2-224/B/4, Poona Space, 3rd Floor, Yousufguda, Hyderabad - 500045</p><p>040-23739542 | hrteam@bedatatech.com</p><div class="title">PAY SLIP FOR THE MONTH OF '.$e($period).'</div></div><table class="info"><tr><td class="label">Employee Name</td><td>'.$e($d['employee_name']).'</td><td class="label">Employee Code</td><td>'.$e($d['employee_id']).'</td></tr><tr><td class="label">Father Name</td><td>'.$e($d['father_name']).'</td><td class="label">Date of Joining</td><td>'.$e($d['date_of_joining']).'</td></tr><tr><td class="label">PAN</td><td>'.$e($d['pan_number']).'</td><td class="label">Bank A/c No.</td><td>'.$e($d['bank_account_number']).'</td></tr><tr><td class="label">UAN / PF A/c</td><td>'.$e($d['uan_number']).' / '.$e($d['pf_account_number']).'</td><td class="label">Bank / Pay Mode</td><td>'.$e($d['ifsc_code']).' / '.$e($d['bank_name']).' / '.$e($d['pay_mode']).'</td></tr><tr><td class="label">Designation</td><td>'.$e($d['designation']).'</td><td class="label">ESI A/c No.</td><td>'.$e($d['esi_number']).'</td></tr><tr><td class="label">Department / Location</td><td>'.$e($d['department']).' / '.$e($d['location']).'</td><td class="label">Gender / DOB</td><td>'.$e($d['gender']).' / '.$e($d['date_of_birth']).'</td></tr><tr><td class="label">Permanent Address</td><td colspan="3">'.$e($d['permanent_address']).'</td></tr></table><table class="section"><tr><th>Month Days</th><th>Weekends</th><th>Paid Holidays</th><th>Working Days</th><th>Present</th><th>Half Days</th><th>PL</th><th>CL</th><th>UPL</th><th>Payable</th></tr><tr><td>'.($month?$month->format('t'):'').'</td><td>'.$e($d['weekend_days']).'</td><td>'.$e($d['holiday_days']).'</td><td>'.$e($d['working_days']).'</td><td>'.$e($d['present_days']).'</td><td>'.$e($d['half_days']).'</td><td>'.$e($d['pl_days']).'</td><td>'.$e($d['cl_days']).'</td><td>'.$e($d['upl_days']).'</td><td>'.$e($d['payable_days']).'</td></tr></table><table class="section"><tr><th>Leave Type</th><th>Opening Balance</th><th>Leaves Availed</th><th>Closing Balance</th></tr>'.$leaveRows.'</table><table class="section"><tr><th>Earnings</th><th>Amount (Rs.)</th><th>Deductions</th><th>Amount (Rs.)</th></tr>'.$payRows.'<tr class="strong"><td>Gross Earnings</td><td class="num">'.$m($gross).'</td><td>Total Deductions</td><td class="num">'.$m($ded).'</td></tr><tr class="net strong"><td colspan="3">NET PAY</td><td class="num">'.$m($net).'</td></tr></table><table class="section"><tr><th colspan="3">Employer Contribution / CTC</th><th>Amount (Rs.)</th></tr><tr><td colspan="3">Employer PF + Pension Fund + Employer ESI + Other CTC</td><td class="num">'.$m($employerPf+$pension+$employerEsi+$ctcOther).'</td></tr><tr class="strong"><td colspan="3">TOTAL MONTHLY CTC</td><td class="num">'.$m($ctc).'</td></tr></table>'.(!empty($d['notes'])?'<p><b>Notes:</b> '.$e($d['notes']).'</p>':'').'<div class="footer">This is a computer-generated payslip<br><span class="muted">No signature is required.</span></div></body></html>';
 $options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$dompdf=new Dompdf\Dompdf($options);$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4','portrait');$dompdf->render();return $dompdf->output();
}
function payrollSend($id,$user){global $conn;$p=payrollFind($id);if(!$p){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Payslip not found.']);return;}$d=$p['snapshot'];$to=$d['payroll_email']??'';if(!filter_var($to,FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Employee payroll email is invalid.']);return;}$name=htmlspecialchars($d['employee_name'],ENT_QUOTES,'UTF-8');$month=htmlspecialchars($d['pay_month'],ENT_QUOTES,'UTF-8');$net=number_format($p['net_pay'],2);$html='<div style="font-family:Arial;max-width:650px;margin:auto;border:1px solid #ddd"><div style="background:#172554;color:white;padding:25px"><img src="cid:brand-logo" alt="BeeData" style="display:block;width:260px;max-width:80%;height:auto;background:white;padding:10px;border-radius:8px"><p>Confidential Payroll</p></div><div style="padding:25px"><h2>Payslip for '.$month.'</h2><p>Hello <strong>'.$name.'</strong>,</p><p>Your monthly payslip has been generated. Net pay: <strong>Rs. '.$net.'</strong>.</p><p>The official payslip is attached as a PDF. Please contact HR if any information needs review.</p><p>Regards,<br><strong>BeeData Technologies HR</strong></p></div></div>';(new ReminderEmailService((new UserSmtpCredentialService())->config((int)$user['id'])))->sendHtml($to,$d['employee_name'],'BeeData Technologies Payslip - '.$month,$html,'Your BeeData Technologies payslip is attached.',payrollPdf($p),$p['payslip_number'].'.pdf',__DIR__.'/../../assets/beedata-logo.png');$s=$conn->prepare("UPDATE employee_payslips SET status='sent',sent_at=NOW() WHERE id=?");$s->bind_param('i',$id);$s->execute();echo json_encode(['success'=>true,'message'=>'Payslip sent successfully to '.$to.'.','data'=>payrollFind($id)]);}
function payrollCreateOnboardingInvite($user){global $conn;$in=json_decode(file_get_contents('php://input'),true)?:[];$email=strtolower(trim((string)($in['personal_email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('A valid employee personal email is required.');$base=rtrim((string)($in['app_url']??''),'/');if(!preg_match('#^https?://(localhost(:\d+)?|e2e\.bedatatech\.com)$#i',$base))throw new InvalidArgumentException('Invalid application URL.');$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$uid=(int)$user['id'];$s=$conn->prepare('INSERT INTO employee_onboarding_invites(personal_email,token_hash,created_by,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY))');$s->bind_param('ssi',$email,$hash,$uid);$s->execute();$url=$base.'/employee-onboarding/'.$token;$name='New Employee';$html='<h2>BeeData Technologies Employee Details</h2><p>Please use the secure link below to complete your employee and payroll profile. The link expires in 7 days and can be submitted once.</p><p><a href="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'">Complete Employee Details</a></p>';(new ReminderEmailService((new UserSmtpCredentialService())->config($uid)))->sendHtml($email,$name,'Complete your BeeData employee details',$html,'Complete your employee details: '.$url);return ['success'=>true,'message'=>'Secure onboarding form sent to '.$email.'.','public_url'=>$url,'expires_in_days'=>7];}
function payrollOnboardingStatus($token){global $conn;$hash=hash('sha256',(string)$token);$s=$conn->prepare('SELECT personal_email,expires_at,completed_at FROM employee_onboarding_invites WHERE token_hash=?');$s->bind_param('s',$hash);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r||$r['completed_at']||strtotime($r['expires_at'])<time()){http_response_code(410);echo json_encode(['success'=>false,'message'=>'This onboarding link is invalid, expired, or already completed.']);return;}echo json_encode(['success'=>true,'personal_email'=>$r['personal_email']]);}
function payrollSubmitOnboarding($token){global $conn;$in=json_decode(file_get_contents('php://input'),true)?:[];$hash=hash('sha256',(string)$token);foreach(['firstname','lastname','birthdate','gender','address','contact_info'] as $k)if(trim((string)($in[$k]??''))===''){http_response_code(422);echo json_encode(['success'=>false,'message'=>$k.' is required.']);return;}$conn->begin_transaction();try{$s=$conn->prepare('SELECT * FROM employee_onboarding_invites WHERE token_hash=? AND completed_at IS NULL AND expires_at>NOW() FOR UPDATE');$s->bind_param('s',$hash);$s->execute();$invite=$s->get_result()->fetch_assoc();if(!$invite)throw new DomainException('This onboarding link is invalid, expired, or already completed.');$r=$conn->query("SELECT employee_id FROM employees WHERE employee_id REGEXP '^EMP-I-[0-9]+$' ORDER BY CAST(SUBSTRING(employee_id,7) AS UNSIGNED) DESC LIMIT 1 FOR UPDATE")->fetch_assoc();$next=$r?((int)substr($r['employee_id'],6)+1):1;$employeeCode='EMP-I-'.$next;$profile=['father_name'=>$in['father_name']??'','pan_number'=>$in['pan_number']??'','uan_number'=>$in['uan_number']??'','pf_account_number'=>$in['pf_account_number']??'','esi_number'=>$in['esi_number']??'','bank_name'=>$in['bank_name']??'','bank_account_number'=>$in['bank_account_number']??'','ifsc_code'=>$in['ifsc_code']??'','date_of_joining'=>$in['date_of_joining']??'','pay_mode'=>$in['pay_mode']??'Bank Transfer','department'=>$in['department']??'','location'=>'Visakhapatnam','date_of_birth'=>$in['birthdate'],'gender'=>$in['gender'],'permanent_address'=>$in['address']];$profileJson=json_encode(payrollSecureData($profile,true),JSON_UNESCAPED_SLASHES);$salary=max(0,(float)($in['monthly_salary']??0));$insert=$conn->prepare('INSERT INTO employees(employee_id,firstname,lastname,address,birthdate,date_of_joining,contact_info,payroll_email,monthly_salary,gender,payroll_profile,created_on) VALUES(?,?,?,?,?,?,?,?,?,?,NOW())');$insert->bind_param('ssssssssdss',$employeeCode,$in['firstname'],$in['lastname'],$in['address'],$in['birthdate'],$in['date_of_joining'],$in['contact_info'],$invite['personal_email'],$salary,$in['gender'],$profileJson);$insert->execute();$eid=$conn->insert_id;$done=$conn->prepare('UPDATE employee_onboarding_invites SET completed_at=NOW(),employee_id=? WHERE id=?');$done->bind_param('ii',$eid,$invite['id']);$done->execute();$conn->commit();echo json_encode(['success'=>true,'message'=>'Your employee details were submitted successfully.','employee_id'=>$employeeCode]);}catch(Throwable $e){$conn->rollback();http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}}
?>
